import React, { useState } from "react";
import "./SidePanel.css";

const SidePanel = ({
  status,
  featuresCount,
  onLogout,
  onSyncData,
  buildingsLoading,
  backendStatus,
  geoServerStatus,
  geoServerFeaturesCount,
  onAddBuilding,
  onManageBuildings, // ✅ CAMBIADO: Ahora es onManageBuildings
  onToggleCoordinateDetection,
  coordinateDetectionActive = false,
  // ❌ ELIMINADOS: onManageRooms, onEditRoom, onCreateRooms
}) => {
  const [activeMenu, setActiveMenu] = useState(null);

  const toggleMenu = (menuName) => {
    setActiveMenu(activeMenu === menuName ? null : menuName);
  };

  const handleLogout = () => {
    console.log("Cerrando sesión...");
    if (onLogout) onLogout();
  };

  const handleSyncClick = () => {
    if (onSyncData) {
      onSyncData();
    }
  };

  const handleAddBuilding = () => {
    console.log("🟢 SidePanel: Agregar Edificio clickeado");
    if (onAddBuilding) {
      onAddBuilding();
    } else {
      console.error("❌ onAddBuilding no está definido");
    }
  };

  const handleManageBuildings = () => {
    console.log("🏢 SidePanel: Gestionar Edificios clickeado");
    if (onManageBuildings) {
      onManageBuildings();
    } else {
      console.error("❌ onManageBuildings no está definido");
      alert("La función de gestión no está disponible");
    }
  };

  // ✅ Manejar toggle de detección de coordenadas
  const handleToggleCoordinateDetection = () => {
    console.log("📍 Botón detección de coordenadas clickeado");
    if (onToggleCoordinateDetection) {
      onToggleCoordinateDetection();
    } else {
      console.error("❌ onToggleCoordinateDetection no está definido");
    }
  };

  const getStatusStyle = () => {
    const baseStyle = {
      padding: "10px",
      borderRadius: "5px",
      textAlign: "center",
      fontSize: "12px",
      fontWeight: "bold",
      color: "white",
      marginBottom: "10px",
    };

    if (backendStatus === "error") {
      return { ...baseStyle, backgroundColor: "#e74c3c" };
    }

    switch (status) {
      case "success":
        return { ...baseStyle, backgroundColor: "#2ecc71" };
      case "empty":
        return { ...baseStyle, backgroundColor: "#f39c12" };
      case "error":
        return { ...baseStyle, backgroundColor: "#e74c3c" };
      default:
        return { ...baseStyle, backgroundColor: "#3498db" };
    }
  };

  const getStatusText = () => {
    if (backendStatus === "error") {
      return "❌ Error conectando al backend";
    }

    switch (status) {
      case "checking":
        return "🔍 Conectando...";
      case "loading":
        return "⏳ Cargando edificios...";
      case "empty":
        return "⚠️ Base de datos vacía";
      case "error":
        return "❌ Error de conexión";
      default:
        return "Estado desconocido";
    }
  };

  return (
    <div className="Panel">
      <div className="dropdowns-container">
        {/* ✅ DROPDOWN UNIFICADO PARA EDIFICIOS Y SALAS */}
        <div
          className={`dropdown ${activeMenu === "Edificios" ? "active" : ""}`}>
          <button
            className="dropdown-toggle"
            onClick={() => toggleMenu("Edificios")}>
            🏢 Edificios y Salas {activeMenu === "Edificios" ? "▲" : "▼"}
          </button>
          {activeMenu === "Edificios" && (
            <ul className="dropdown-menu">
              {/* SECCIÓN EDIFICIOS */}
              <li className="dropdown-section">
                <strong>🏢 Edificios</strong>
              </li>
              <li>
                <button onClick={handleAddBuilding}>➕ Agregar Edificio</button>
              </li>
              <li>
                <button onClick={handleManageBuildings}>
                  📝 Gestionar Edificios
                </button>
              </li>

              {/* SEPARADOR */}
              <li className="dropdown-divider"></li>

              {/* SECCIÓN SALAS */}
              <li className="dropdown-section">
                <strong>🚪 Salas</strong>
              </li>
              <li>
                <button onClick={handleManageBuildings}>➕ Crear Salas</button>
              </li>
              <li>
                <button onClick={handleManageBuildings}>
                  ✏️ Gestionar Salas
                </button>
              </li>
            </ul>
          )}
        </div>

        {/* ✅ DROPDOWN PARA RUTAS (MANTENIDO) */}
        <div className={`dropdown ${activeMenu === "Rutas" ? "active" : ""}`}>
          <button
            className="dropdown-toggle"
            onClick={() => toggleMenu("Rutas")}>
            🗺️ Rutas {activeMenu === "Rutas" ? "▲" : "▼"}
          </button>
          {activeMenu === "Rutas" && (
            <ul className="dropdown-menu">
              <li>
                <button onClick={() => alert("Funcionalidad en desarrollo")}>
                  ➕ Agregar Ruta
                </button>
              </li>
              <li>
                <button onClick={() => alert("Funcionalidad en desarrollo")}>
                  ✏️ Editar Ruta
                </button>
              </li>
              <li>
                <button onClick={() => alert("Funcionalidad en desarrollo")}>
                  🗑️ Eliminar Ruta
                </button>
              </li>
            </ul>
          )}
        </div>
      </div>

      {/* ✅ BOTÓN: Detección de coordenadas (MANTENIDO) */}
      <div className="coordinate-detection-section">
        <button
          className={`coordinate-detection-btn ${
            coordinateDetectionActive ? "active" : ""
          }`}
          onClick={handleToggleCoordinateDetection}>
          {coordinateDetectionActive
            ? "📍 Capturando..."
            : "📍 Capturar Coordenadas"}
        </button>
        {coordinateDetectionActive && (
          <small
            style={{
              color: "#e74c3c",
              display: "block",
              textAlign: "center",
              marginTop: "5px",
            }}>
            Haz clic en el mapa
          </small>
        )}
      </div>

      {/* ✅ BOTÓN: Sincronizar datos (MANTENIDO) */}
      <div className="sync-section">
        <button className="sync-btn" onClick={handleSyncClick}>
          🔄 Sincronizar con GeoServer
        </button>
        <div className="sync-info">
          <small>GeoServer: {geoServerFeaturesCount} elementos</small>
        </div>
      </div>

      {/* ✅ ESTADO DEL SISTEMA (MANTENIDO) */}
      <div className="status-section">
        <div style={getStatusStyle()}>{getStatusText()}</div>
        <div className="features-count">
          📊 Edificios cargados: {featuresCount}
        </div>
        {buildingsLoading && (
          <div className="loading-indicator">⏳ Cargando...</div>
        )}
      </div>

      <button className="logout-btn" onClick={handleLogout}>
        Cerrar Sesión
      </button>
    </div>
  );
};

export default SidePanel;
